        return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        return datetime.date.today()

def load(name, *alts):
    v = vars.get(name)
    if isinstance(v, (dict, list)):
        return v
    if isinstance(v, str) and v.strip():
        try:
            return json.loads(v)
        except Exception:
            pass
    for a in alts:
        v = vars.get(a)
        if isinstance(v, (dict, list)):
            return v
        if isinstance(v, str) and v.strip():
            try:
                return json.loads(v)
